import {menuHTML} from '/site-navigation.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed=document.querySelector('[data-navigation-bootstrap]');const data=seed?JSON.parse(seed.textContent):await(await fetch('/api/navigation')).json();
const nav=document.querySelector('.nav'),drawer=document.querySelector('[data-drawer]'),mega=document.querySelector('[data-megapanel]');nav.innerHTML=menuHTML(data.items);drawer.innerHTML='<div class="scrim" data-close-drawer></div><div class="panel" role="dialog" aria-label="Menu"><button data-close-drawer class="btn ghost">Close menu</button>'+menuHTML(data.items,true)+'</div>';
document.addEventListener('click',e=>{const button=e.target.closest('[data-mega]');if(button){const item=data.items.find(i=>i.key===button.dataset.mega),open=button.getAttribute('aria-expanded')!=='true';nav.querySelectorAll('[data-mega]').forEach(b=>b.setAttribute('aria-expanded',false));mega.classList.toggle('open',open);button.setAttribute('aria-expanded',open);if(open)mega.querySelector('.in').innerHTML=item.groups.map(g=>'<div class="col"><h4>'+esc(g.label)+'</h4>'+g.links.filter(l=>l.active!==false).map(l=>`<a href="${esc(l.href)}">${esc(l.label)}</a>`).join('')+'</div>').join('');}else if(e.target.closest('[data-burger]'))drawer.classList.toggle('open');else if(e.target.closest('[data-close-drawer]'))drawer.classList.remove('open');else if(e.target.closest('[data-cart-open],[data-cart]'))location.assign('/satin/checkout/');else if(e.target.closest('[data-quote]'))location.assign('/satin/contact/');else if(!e.target.closest('.hdr')){mega.classList.remove('open');nav.querySelectorAll('[data-mega]').forEach(b=>b.setAttribute('aria-expanded',false));}});
document.querySelector('[data-language]')?.addEventListener('change',e=>location.assign('/satin/'+(e.target.value==='en'?'':e.target.value+'/')+'checkout/'));
